// Generated by vibelang from src/shell/titlebar/tab-title.ts; the migrate flow writes it again with each batch.
import { isFallbackTitle } from "@opencode/util/session-title-fallback";
// Draft, preparing, and untitled session tabs share one localized label.
export function sessionTabTitle(title, fallback) {
    return !title || isFallbackTitle(title) ? fallback : title;
}
